// ===== Generate today's clinic data (DEMO) =====
// Replace this node later with "Read Excel from Google Drive / OneDrive" and the ads connections.
const now = new Date();
const dubai = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Dubai' }));
const day = new Date(dubai); day.setDate(day.getDate() - 1);          // report on yesterday
const dateStr = day.toISOString().slice(0, 10);
let seed = Number(dateStr.replace(/-/g, ''));
const rnd = () => { seed = (seed * 1664525 + 1013904223) % 4294967296; return seed / 4294967296; };
const pick = a => a[Math.floor(rnd() * a.length)];
const weekend = [5, 6].includes(day.getDay()) ? 1.2 : 1;

const SERVICES = { 'Botox': 1200, 'Fillers': 1500, "Men's Botox & filler": 1450, 'IV drip': 650, 'Facial': 450, 'Chemical peel': 750, 'Hijama': 250,
  'Teeth cleaning': 350, 'Dental implant': 4800, '3D veneers': 9500, '6D veneers': 18000, 'Liposuction': 14000, 'Eyelid surgery': 9500 };
const ADS = [
  ['Instagram', 'Botox reel (Arabic)', 'Botox', 410, 13, .22, .81, .86],
  ['Instagram', '6D veneers carousel', '6D veneers', 330, 2, .10, .84, .82],
  ['Instagram', "Men's Botox reel", "Men's Botox & filler", 210, 5, .20, .80, .79],
  ['Facebook', 'Implant "AED 99" lead form', 'Dental implant', 290, 17, .012, .35, .27],
  ['TikTok', 'Liposuction transformation', 'Liposuction', 310, 10, .015, .50, .38],
  ['Snapchat', 'IV drip weekend story', 'IV drip', 175, 8, .14, .71, .41],
  ['Facebook', 'Hijama (Arabic)', 'Hijama', 95, 7, .34, .83, .88],
  ['TikTok', 'Teeth cleaning AED 199', 'Teeth cleaning', 185, 10, .27, .74, .69],
  ['Facebook', 'Eyelid surgery (English)', 'Eyelid surgery', 240, 3, .04, .78, .43],
  ['Instagram', 'Peel & facial UGC', 'Chemical peel', 135, 6, .20, .79, .84],
  ['Snapchat', '3D veneers smile reveal', '3D veneers', 215, 7, .03, .55, .52],
  ['Facebook', 'Lip filler "limited offer"', 'Fillers', 95, 5, .03, 0, .31]
];
const AGENTS = ['Hassan J.','Fadi Z.','Khaled H.','Salma Q.','Nour O.','Aya A.','Ziad B.','Reem U.','Karim N.','Mona I.','Lina E.','Ahmed X.','Tarek L.','Sami P.','Yousef V.','Mariam C.','Hala S.','Huda W.','Dina G.','Adel D.'];
const DOCTORS = ['Dr. Sara M.','Dr. Huda R.','Dr. Adel K.','Dr. Lina S.','Dr. Reem A.','Dr. Fadi N.','Dr. Mona Y.','Dr. Ziad H.','Dr. Tarek B.','Dr. Dina F.'];
const NAT = [['GCC', 1], ['Arab expat', 1], ['Western expat', 1], ['South Asian expat', 0], ['Southeast Asian expat', 0], ['Other', 0]];

const adRows = [], leads = [], appointments = [], payments = [];
let leadId = 1;
for (const [platform, ad, service, spendBase, leadsBase0, book, show, onTarget] of ADS) {
  const leadsBase = leadsBase0 * 1.3;
  // hourly ad stats (like an Ads Manager export)
  let adLeads = Math.round(leadsBase * weekend * (0.7 + rnd() * 0.6));
  for (let h = 0; h < 24; h++) {
    const w = h < 8 ? 0.2 : h > 21 ? 0.6 : 1.2;
    adRows.push({ date: dateStr, hour: h, platform, ad, service, spend: +(spendBase / 24 * w * (0.7 + rnd() * 0.6)).toFixed(2), impressions: Math.round(400 * w * (0.6 + rnd())), clicks: Math.round(9 * w * (0.5 + rnd())) });
  }
  for (let i = 0; i < adLeads; i++) {
    const team = rnd() < 0.5 ? 'A' : 'B';
    const agent = team === 'A' ? pick(AGENTS.slice(0, 10)) : pick(AGENTS.slice(10));
    const reply = Math.round((team === 'A' ? 4 : 10) + rnd() * (team === 'A' ? 20 : 70));
    const target = rnd() < onTarget;
    const nat = target ? pick(NAT.filter(n => n[1]))[0] : pick(NAT.filter(n => !n[1]))[0];
    const booked = rnd() < book * (reply < 15 ? 1.4 : 0.7);
    const lead = { lead_id: 'L' + dateStr.replace(/-/g, '') + String(leadId++).padStart(4, '0'), source: 'Ads', platform, ad, service, team, agent, first_reply_min: reply, nationality_group: nat, city: rnd() < 0.66 ? 'Dubai' : pick(['Sharjah', 'Abu Dhabi', 'Ajman']), booked };
    leads.push(lead);
    if (booked) {
      const showed = rnd() < show;
      appointments.push({ lead_id: lead.lead_id, service, doctor: pick(DOCTORS), status: showed ? 'Attended' : 'No-show' });
      if (showed) payments.push({ lead_id: lead.lead_id, service, amount: SERVICES[service], source: 'Ads', agent });
    }
  }
}
// sales outreach + organic patients (no ad cost)
for (const [src, n] of [['Sales outreach', Math.round(6 + rnd() * 6)], ['Organic', Math.round(9 + rnd() * 8)]]) {
  for (let i = 0; i < n; i++) {
    const service = pick(Object.keys(SERVICES).filter(s => SERVICES[s] < 5000 || rnd() < 0.15));
    payments.push({ lead_id: null, service, amount: SERVICES[service], source: src, agent: src === 'Sales outreach' ? pick(AGENTS) : null, channel: src === 'Organic' ? pick(['Google Maps', 'Walk-in', 'Referral', 'Instagram (no ad)']) : 'Call list' });
  }
}
const reviews = Array.from({ length: Math.round(1 + rnd() * 4) }, () => ({ stars: pick([5, 5, 5, 5, 4, 4, 3, 1]), doctor: pick(DOCTORS), replied: rnd() < 0.7 }));
const reports = { expected: 40, received: Math.round(33 + rnd() * 6), blockers: Math.round(1 + rnd() * 4) };

return [{ json: { date: dateStr, rows: adRows.length + leads.length + appointments.length + payments.length, adRows, leads, appointments, payments, reviews, reports } }];

// ===== Compute KPIs (plain code, no AI) =====
const d = $input.first().json;
const sum = (a, f) => a.reduce((s, x) => s + f(x), 0);
const group = (a, k) => a.reduce((m, x) => ((m[x[k]] = m[x[k]] || []).push(x), m), {});

const spend = sum(d.adRows, r => r.spend);
const revenue = sum(d.payments, p => p.amount);
const bySource = Object.fromEntries(Object.entries(group(d.payments, 'source')).map(([s, a]) => [s, { patients: a.length, revenue: sum(a, p => p.amount) }]));
const adsRev = (bySource.Ads || { revenue: 0 }).revenue;

const ads = Object.entries(group(d.adRows, 'ad')).map(([ad, rows]) => {
  const L = d.leads.filter(l => l.ad === ad);
  const P = d.payments.filter(p => p.source === 'Ads' && L.some(l => l.lead_id === p.lead_id));
  const sp = sum(rows, r => r.spend), rv = sum(P, p => p.amount);
  return { ad, platform: rows[0].platform, spend: Math.round(sp), leads: L.length, patients: P.length, revenue: rv, roas: sp ? +(rv / sp).toFixed(1) : 0,
           onTarget: L.length ? Math.round(100 * L.filter(l => ['GCC', 'Arab expat', 'Western expat'].includes(l.nationality_group)).length / L.length) : 0 };
}).sort((a, b) => b.roas - a.roas);

const teams = Object.entries(group(d.leads, 'team')).map(([t, L]) => ({ team: t, leads: L.length, booked: L.filter(l => l.booked).length,
  avgReply: Math.round(sum(L, l => l.first_reply_min) / L.length), slow: L.filter(l => l.first_reply_min > 30).length })).sort((a, b) => a.team.localeCompare(b.team));
const agents = Object.entries(group(d.leads, 'agent')).map(([a, L]) => ({ agent: a, leads: L.length, booked: L.filter(l => l.booked).length, avgReply: Math.round(sum(L, l => l.first_reply_min) / L.length) }));
const slowest = agents.slice().sort((a, b) => b.avgReply - a.avgReply).slice(0, 3);
const best = agents.slice().sort((a, b) => b.booked - a.booked)[0];

const noShow = d.appointments.filter(a => a.status === 'No-show').length;
const onTarget = Math.round(100 * d.leads.filter(l => ['GCC', 'Arab expat', 'Western expat'].includes(l.nationality_group)).length / d.leads.length);
const outsideDubai = Math.round(100 * d.leads.filter(l => l.city !== 'Dubai').length / d.leads.length);
const badReviews = d.reviews.filter(r => r.stars <= 2 && !r.replied).length;

const kpis = {
  date: d.date, rowsProcessed: d.rows,
  revenue, adSpend: Math.round(spend), adsRevenue: adsRev, adsProfit: Math.round(adsRev - spend), roas: +(adsRev / spend).toFixed(1),
  bySource, leads: d.leads.length, booked: d.appointments.length, attended: d.appointments.length - noShow, noShow,
  onTargetPct: onTarget, outsideDubaiPct: outsideDubai,
  bestAd: ads[0], worstAd: ads[ads.length - 1], zeroPatientAds: ads.filter(a => a.patients === 0 && a.spend > 50).map(a => `${a.platform} · ${a.ad} (AED ${a.spend})`),
  teams, slowestAgents: slowest, bestAgent: best,
  reviews: { new: d.reviews.length, avg: d.reviews.length ? +(sum(d.reviews, r => r.stars) / d.reviews.length).toFixed(1) : null, badUnanswered: badReviews },
  teamReports: d.reports
};
// short text summary for the AI (a few lines instead of thousands of rows)
const f = n => Math.round(n).toLocaleString('en-US');
const summary = [
  `Date: ${d.date} · rows processed: ${d.rows}`,
  `Revenue AED ${f(revenue)} · Ads AED ${f(adsRev)} · Sales outreach AED ${f((bySource['Sales outreach']||{revenue:0}).revenue)} · Organic AED ${f((bySource.Organic||{revenue:0}).revenue)}`,
  `Ad spend AED ${f(spend)} · ads profit AED ${f(adsRev - spend)} · ROAS ${kpis.roas}x`,
  `Leads ${kpis.leads} · booked ${kpis.booked} · attended ${kpis.attended} · no-shows ${noShow}`,
  `On-target leads ${onTarget}% (target 70%) · leads outside Dubai ${outsideDubai}%`,
  `Best ad: ${ads[0].platform} ${ads[0].ad} · ${ads[0].patients} patients · ROAS ${ads[0].roas}x`,
  `Worst ad: ${kpis.worstAd.platform} ${kpis.worstAd.ad} · AED ${kpis.worstAd.spend} spent · ${kpis.worstAd.patients} patients`,
  `Ads with spend and zero patients: ${kpis.zeroPatientAds.join('; ') || 'none'}`,
  ...teams.map(t => `Team ${t.team}: ${t.leads} leads, ${t.booked} booked, avg first reply ${t.avgReply} min, ${t.slow} leads waited >30 min`),
  `Slowest agents: ${slowest.map(a => `${a.agent} ${a.avgReply} min`).join(', ')} · best: ${best.agent} ${best.booked} bookings`,
  `Google: ${kpis.reviews.new} new reviews, avg ${kpis.reviews.avg}, ${badReviews} bad review(s) without reply`,
  `Team reports: ${d.reports.received}/${d.reports.expected} received, ${d.reports.blockers} blockers`
].join('\n');
const system = `You are the AI analyst for Glow Up Clinic, a cosmetic, dental and wellness clinic in Dubai.
You receive yesterday's numbers, already calculated. Never invent numbers; use only what you receive.
Write the owner's morning brief for Telegram in clear, simple English:
- Start with "Good morning · Glow Up daily brief" and the date.
- Money: revenue, and split by ads / sales outreach / organic; ad spend, ads profit and ROAS.
- Ads: best ad, worst ad, ads that spent money and brought no patients, on-target share.
- Sales: both teams' reply time and bookings, slowest agents, best agent.
- Google reviews and team reports in one line each.
- End with "Today:" and exactly 3 numbered actions, each one specific (who does what).
Use a few emojis as section markers. Max 1,500 characters. No markdown tables. Last line: "Sample data (demo)".`;
const body = { model: 'nousresearch/hermes-4-405b', temperature: 0.3, messages: [{ role: 'system', content: system }, { role: 'user', content: summary }] };
return [{ json: { kpis, summary, body } }];

const r = $input.first().json;
const text = (r.choices && r.choices[0] && r.choices[0].message && r.choices[0].message.content) || ('⚠️ Brief could not be written. Raw numbers:\n' + $('Compute KPIs').first().json.summary);
return [{ json: { telegram: text.slice(0, 3900) } }];

// ===== Live status for the dashboard network page =====
const k = $('Compute KPIs').first().json.kpis;
const status = { lastRun: new Date().toISOString(), reportDate: k.date, rowsProcessed: k.rowsProcessed,
  agents: [
    { id: 'ads', name: 'Ads Analyst', state: 'done', result: `${k.zeroPatientAds.length} ads flagged · ROAS ${k.roas}x` },
    { id: 'sales', name: 'Sales Coach', state: 'done', result: k.teams.map(t => `Team ${t.team} ${t.avgReply} min`).join(' · ') },
    { id: 'ops', name: 'Operations', state: 'done', result: `${k.attended} attended · ${k.noShow} no-shows` },
    { id: 'reviews', name: 'Reviews Monitor', state: 'done', result: `${k.reviews.new} new reviews · avg ${k.reviews.avg}` },
    { id: 'reports', name: 'Team Reports Reader', state: 'done', result: `${k.teamReports.received}/${k.teamReports.expected} reports` },
    { id: 'brief', name: 'Brief Writer', state: 'done', result: 'Brief sent to Telegram 08:00' }
  ],
  totals: { revenue: k.revenue, leads: k.leads, booked: k.booked, adSpend: k.adSpend } };
return [{ json: { message: `glowup status ${k.date}`, content: Buffer.from(JSON.stringify(status, null, 1), 'utf8').toString('base64') } }];
